/**
 * A value that may or may not be present — like `Result` but with no error
 * payload. Check `.ok` before reading `.value`.
 *
 * @typeParam T - the type of the value when present
 *
 * @example
 * function first<T>(xs: T[]): Option<T> {
 *   return xs.length > 0 ? { ok: true, value: xs[0] } : { ok: false };
 * }
 */
export type Option<T> = {
    ok: true;
    value: T;
} | {
    ok: false;
};
/**
 * The outcome of a call that might fail: either a success carrying a `value`,
 * or a failure carrying an `error`. Always check `.ok` first — TypeScript then
 * lets you read `.value` (when `true`) or `.error` (when `false`).
 *
 * @typeParam T - the success value type
 * @typeParam E - the error type (often `string`)
 *
 * @example
 * function makeSection(cap: number): Result<Section, string> {
 *   if (cap <= 0) return Result.err("Capacity must be > 0");
 *   return Result.ok({ capacity: cap, enrolled: { kind: "empty" } });
 * }
 */
export type Result<T, E> = {
    ok: true;
    value: T;
} | {
    ok: false;
    error: E;
};
/** Helpers for building and unwrapping {@link Result} values. */
export declare const Result: {
    /**
     * Wrap a success value in an ok `Result`.
     * @example Result.ok(42) // { ok: true, value: 42 }
     */
    ok: <T>(value: T) => Result<T, never>;
    /**
     * Wrap an error in a failed `Result`.
     * @example Result.err("not found") // { ok: false, error: "not found" }
     */
    err: <E>(error: E) => Result<never, E>;
};
